//! Vectors for the verifier's side of LKP (`blocks/iop/lkp.h`), generated by
//! `scripts/cpp_vectors/lkp_vectors.cpp`.

#![allow(non_snake_case)]

use std::collections::HashMap;

use fp_core::chain::public::PublicBytes;
use fp_core::field::ext::{F, E};
use fp_core::iop::lkp::{
    lkp_block_of, lkp_by_variable, lkp_count, lkp_cube, lkp_cube_tensor, lkp_cube_weight,
    lkp_cubes,
    lkp_default_order, lkp_fault, lkp_in_order, lkp_is_padding, lkp_key_claim, lkp_live_blocks,
    lkp_masks, lkp_on_block, lkp_only_padding, lkp_order_beginning, lkp_padding_count,
    lkp_range_order, lkp_row, lkp_rows, lkp_shape, lkp_summand_bits, lkp_summand_leaves,
    lkp_summand_product, lkp_summand_tie, lkp_table_at, lkp_weights_of_block, lkp_key_masks,
    LkpCube, LkpKeyBlock, LkpPadding, LkpPublic, LkpTablePart,
};
use fp_core::iop::message::Writer;
use fp_core::iop::summand::{PointClaim, Summand};
use fp_core::iop::tensor::{Form, Tensor};

const VECTORS: &str = include_str!("../../fixtures/lkp_vectors.txt");

fn fields(line: &str) -> HashMap<&str, &str> {
    line.split_whitespace()
        .filter_map(|t| t.split_once('='))
        .map(|(k, v)| (k, v))
        .collect()
}
fn e(s: &str) -> E {
    let p: Vec<&str> = s.split(',').collect();
    E([
        F(u64::from_str_radix(p[0], 16).unwrap()),
        F(u64::from_str_radix(p[1], 16).unwrap()),
        F(u64::from_str_radix(p[2], 16).unwrap()),
    ])
}
fn mk(x: u64) -> E {
    E([F(x), F(x + 1), F(x + 2)])
}
fn mkvec(n: usize, base: u64) -> Vec<E> {
    (0..n as u64).map(|i| mk(base + i)).collect()
}
fn elist(s: &str) -> Vec<E> {
    if s == "-" {
        return Vec::new();
    }
    s.split(';').map(e).collect()
}
fn u32s(s: &str) -> Vec<u32> {
    if s == "-" {
        return Vec::new();
    }
    s.split(',').map(|x| x.parse().unwrap()).collect()
}
fn e_str(x: E) -> String {
    format!("{:016x},{:016x},{:016x}", x.0[0].0, x.0[1].0, x.0[2].0)
}
fn es(v: &[E]) -> String {
    if v.is_empty() {
        return "-".to_string();
    }
    v.iter().map(|x| e_str(*x)).collect::<Vec<_>>().join(";")
}
fn us(v: &[u32]) -> String {
    if v.is_empty() {
        return "-".to_string();
    }
    v.iter().map(|x| x.to_string()).collect::<Vec<_>>().join(",")
}
fn hex_bytes(b: &[u8]) -> String {
    b.iter().map(|x| format!("{:02x}", x)).collect()
}
fn fault_str(f: Option<&'static str>) -> String {
    match f {
        Some(s) => s.replace(' ', "_"),
        None => "-".to_string(),
    }
}
fn keys_str(v: &[LkpKeyBlock]) -> String {
    if v.is_empty() {
        return "-".to_string();
    }
    v.iter()
        .map(|k| format!("{}:{}:{}:{}", k.first, k.log_trees, k.function, k.padding_row))
        .collect::<Vec<_>>()
        .join(";")
}
fn tables_str(v: &[LkpTablePart]) -> String {
    if v.is_empty() {
        return "-".to_string();
    }
    v.iter()
        .map(|t| format!("{}:{}:{}:{}", t.first, t.log_rows, t.function, es(&t.rows)))
        .collect::<Vec<_>>()
        .join("|")
}
fn padding_str(v: &[LkpPadding]) -> String {
    if v.is_empty() {
        return "-".to_string();
    }
    v.iter()
        .map(|p| format!("{}:{}:{}:{}:{}", p.part, p.first, p.log_step, p.length, p.row))
        .collect::<Vec<_>>()
        .join(";")
}

fn parse_public(kv: &HashMap<&str, &str>) -> LkpPublic {
    let keys = if kv["keys"] == "-" {
        Vec::new()
    } else {
        kv["keys"]
            .split(';')
            .map(|s| {
                let p: Vec<&str> = s.split(':').collect();
                LkpKeyBlock {
                    first: p[0].parse().unwrap(),
                    log_trees: p[1].parse().unwrap(),
                    function: p[2].parse().unwrap(),
                    padding_row: p[3].parse().unwrap(),
                }
            })
            .collect()
    };
    let tables = if kv["tables"] == "-" {
        Vec::new()
    } else {
        kv["tables"]
            .split('|')
            .map(|s| {
                let mut p = s.splitn(4, ':');
                LkpTablePart {
                    first: p.next().unwrap().parse().unwrap(),
                    log_rows: p.next().unwrap().parse().unwrap(),
                    function: p.next().unwrap().parse().unwrap(),
                    rows: elist(p.next().unwrap()),
                }
            })
            .collect()
    };
    let padding = if kv["padding"] == "-" {
        Vec::new()
    } else {
        kv["padding"]
            .split(';')
            .map(|s| {
                let p: Vec<&str> = s.split(':').collect();
                LkpPadding {
                    part: p[0].parse().unwrap(),
                    first: p[1].parse().unwrap(),
                    log_step: p[2].parse().unwrap(),
                    length: p[3].parse().unwrap(),
                    row: p[4].parse().unwrap(),
                }
            })
            .collect()
    };
    LkpPublic {
        parts: u32s(kv["parts"]),
        d: kv["d"].parse().unwrap(),
        mu: kv["mu"].parse().unwrap(),
        live: kv["live"].parse().unwrap(),
        h: kv["h"].parse().unwrap(),
        g: kv["g"].parse().unwrap(),
        shifted: kv["shifted"] == "1",
        read_from: u32s(kv["read_from"]),
        keys,
        tables,
        padding,
        last_key_level_order: u32s(kv["order"]),
    }
}

/// LKP's weights on one part's keys, from the definitions, as the C++ test builds them: the
/// equality vector less one product form per padding cube of a padding-only block and of a run.
fn weights_on_keys(S: &LkpPublic, part: usize, point: &[E]) -> Form {
    let mut f = Form::default();
    f.add(Tensor::eq(point, S.parts[0], E::one()));
    for b in &S.keys {
        if b.function < 0 {
            f.add(lkp_cube_tensor(&lkp_cube(S, b), point, -E::one()));
        }
    }
    for p in &S.padding {
        if p.part as usize != part {
            continue;
        }
        for c in lkp_cubes(p, S.parts[0]) {
            f.add(lkp_cube_tensor(&c, point, -E::one()));
        }
    }
    f
}

fn summand_meta(s: &Summand, kv: &HashMap<&str, &str>, line: &str) {
    assert_eq!(s.shown.to_string(), kv["shown"], "{}", line);
    assert_eq!(s.kept.to_string(), kv["kept"], "{}", line);
    assert_eq!(s.degree.to_string(), kv["degree"], "{}", line);
}

#[test]
fn lkp_vectors_match_the_cpp_reference() {
    let mut publics: HashMap<String, LkpPublic> = HashMap::new();
    let mut seen = 0usize;
    for line in VECTORS.lines() {
        let tag = line.split_whitespace().next().unwrap();
        let kv = fields(line);
        match tag {
            "LKP_PUBLIC" => {
                let S = parse_public(&kv);
                assert_eq!(us(&S.parts), kv["parts"], "{}", line);
                assert_eq!(keys_str(&S.keys), kv["keys"], "{}", line);
                assert_eq!(tables_str(&S.tables), kv["tables"], "{}", line);
                assert_eq!(padding_str(&S.padding), kv["padding"], "{}", line);
                assert_eq!(us(&S.last_key_level_order), kv["order"], "{}", line);
                assert_eq!(S.planes().to_string(), kv["planes"], "{}", line);
                assert_eq!(S.all_keys().to_string(), kv["all_keys"], "{}", line);
                assert_eq!(fault_str(lkp_fault(&S)), kv["fault"], "{}", line);
                let mut w = Writer::default();
                S.public_bytes(&mut w);
                assert_eq!(hex_bytes(w.bytes()), kv["bytes"], "{}", line);
                publics.insert(kv["name"].to_string(), S);
            }
            "LKP_FAULT" => {
                let S = parse_public(&kv);
                assert_eq!(fault_str(lkp_fault(&S)), kv["fault"], "{}", line);
            }
            "LKP_ROWS" => {
                let S = &publics[kv["public"]];
                assert_eq!(es(&lkp_rows(S, e(kv["theta"]))), kv["rows"], "{}", line);
            }
            "LKP_TABLE_AT" => {
                let S = &publics[kv["public"]];
                let point = elist(kv["point"]);
                assert_eq!(
                    e_str(lkp_table_at(S, e(kv["theta"]), &point)),
                    kv["out"],
                    "{}",
                    line
                );
            }
            "LKP_PADDING" => {
                let S = &publics[kv["public"]];
                assert_eq!(lkp_padding_count(S).to_string(), kv["count"], "{}", line);
                assert_eq!(
                    (lkp_only_padding(S) as u8).to_string(),
                    kv["only"],
                    "{}",
                    line
                );
            }
            "LKP_MASKS" => {
                let S = &publics[kv["public"]];
                assert_eq!(lkp_key_masks(S).to_string(), kv["key_masks"], "{}", line);
                assert_eq!(lkp_masks(S).to_string(), kv["masks"], "{}", line);
            }
            "LKP_IS_PADDING" => {
                let S = &publics[kv["public"]];
                let part: u32 = kv["part"].parse().unwrap();
                let i: u64 = kv["i"].parse().unwrap();
                assert_eq!(
                    (lkp_is_padding(S, part, i) as u8).to_string(),
                    kv["value"],
                    "{}",
                    line
                );
            }
            "LKP_ROW" => {
                let S = &publics[kv["public"]];
                let t: u64 = kv["t"].parse().unwrap();
                assert_eq!(
                    e_str(lkp_row(S, e(kv["theta"]), t)),
                    kv["value"],
                    "{}",
                    line
                );
            }
            "LKP_BLOCK" => {
                let S = &publics[kv["public"]];
                let key: u64 = kv["key"].parse().unwrap();
                let b = lkp_block_of(S, key);
                assert_eq!(b.first.to_string(), kv["first"], "{}", line);
                assert_eq!(b.log_trees.to_string(), kv["log_trees"], "{}", line);
                assert_eq!(b.function.to_string(), kv["function"], "{}", line);
                assert_eq!(b.padding_row.to_string(), kv["padding_row"], "{}", line);
            }
            "LKP_SHAPE" => {
                let S = &publics[kv["public"]];
                let shape = lkp_shape(S, e(kv["theta"]));
                assert_eq!(shape.d.to_string(), kv["d"], "{}", line);
                assert_eq!(shape.mu.to_string(), kv["mu"], "{}", line);
                assert_eq!(shape.planes.to_string(), kv["planes"], "{}", line);
                assert_eq!(us(&shape.part_bits), kv["part_bits"], "{}", line);
                assert_eq!(shape.all_keys.to_string(), kv["all_keys"], "{}", line);
                assert_eq!(us(&shape.last_key_level_order), kv["order"], "{}", line);
                let pad = if shape.padding.is_empty() {
                    "-".to_string()
                } else {
                    shape
                        .padding
                        .iter()
                        .map(|(n, row)| format!("{}:{}", n, e_str(*row)))
                        .collect::<Vec<_>>()
                        .join(";")
                };
                assert_eq!(pad, kv["pad"], "{}", line);
                let point = elist(kv["point"]);
                assert_eq!(e_str((shape.table_at)(&point)), kv["table_at"], "{}", line);
            }
            "LKP_KEY_CLAIM" => {
                let S = &publics[kv["public"]];
                let point = elist(kv["point"]);
                let k = lkp_key_claim(
                    S,
                    e(kv["theta"]),
                    e(kv["alpha"]),
                    kv["part"].parse().unwrap(),
                    PointClaim { point, masks: Vec::new(), value: e(kv["value"]) },
                );
                assert_eq!(es(&k.point), kv["point"], "{}", line);
                assert_eq!(e_str(k.target), kv["target"], "{}", line);
                let wvars: u32 = kv["wvars"].parse().unwrap();
                assert_eq!(k.point.len(), wvars as usize, "{}", line);
                assert_eq!(k.weights.tensors.len().to_string(), kv["wcount"], "{}", line);
                assert_eq!(k.masks.len().to_string(), kv["masks"], "{}", line);
                let at: Vec<E> = (0..(1u64 << wvars)).map(|j| k.weights.at(j)).collect();
                assert_eq!(es(&at), kv["wat"], "{}", line);
            }
            "LKP_WEIGHTS_OF_BLOCK" => {
                let S = &publics[kv["public"]];
                let point = elist(kv["point"]);
                let all = weights_on_keys(S, kv["part"].parse().unwrap(), &point);
                let own = lkp_weights_of_block(S, &all, kv["block"].parse().unwrap());
                assert_eq!(S.parts[0].to_string(), kv["wvars"], "{}", line);
                assert_eq!(own.tensors.len().to_string(), kv["wcount"], "{}", line);
                let at: Vec<E> =
                    (0..(1u64 << S.parts[0])).map(|j| own.at(j)).collect();
                assert_eq!(es(&at), kv["at"], "{}", line);
            }
            "LKP_CUBES" => {
                let p = LkpPadding {
                    part: 0,
                    first: kv["first"].parse().unwrap(),
                    log_step: kv["log_step"].parse().unwrap(),
                    length: kv["length"].parse().unwrap(),
                    row: 0,
                };
                let cs = lkp_cubes(&p, kv["bits"].parse().unwrap());
                let s = if cs.is_empty() {
                    "-".to_string()
                } else {
                    cs.iter()
                        .map(|c| format!("{}:{}", c.mask, c.value))
                        .collect::<Vec<_>>()
                        .join(";")
                };
                assert_eq!(s, kv["cubes"], "{}", line);
            }
            "LKP_CUBE_WEIGHT" => {
                let c = LkpCube {
                    mask: kv["mask"].parse().unwrap(),
                    value: kv["value"].parse().unwrap(),
                };
                let z = elist(kv["z"]);
                assert_eq!(e_str(lkp_cube_weight(&c, &z)), kv["out"], "{}", line);
            }
            "LKP_CUBE_TENSOR" => {
                let c = LkpCube {
                    mask: kv["mask"].parse().unwrap(),
                    value: kv["value"].parse().unwrap(),
                };
                let z = elist(kv["z"]);
                let t = lkp_cube_tensor(&c, &z, e(kv["scalar"]));
                assert_eq!(t.vars().to_string(), kv["vars"], "{}", line);
                assert_eq!(e_str(t.scalar), kv["scalar_out"], "{}", line);
                let at: Vec<E> = (0..(1u64 << t.vars())).map(|j| t.at(j)).collect();
                assert_eq!(es(&at), kv["at"], "{}", line);
            }
            "LKP_ORDER" => {
                let out = match kv["kind"] {
                    "default" => lkp_default_order(kv["variables"].parse().unwrap()),
                    "beginning" => {
                        lkp_order_beginning(&u32s(kv["first"]), kv["variables"].parse().unwrap())
                    }
                    "range" => {
                        lkp_range_order(kv["variables"].parse().unwrap(), kv["g"].parse().unwrap())
                    }
                    other => panic!("unknown order kind {}", other),
                };
                assert_eq!(us(&out), kv["out"], "{}", line);
            }
            "LKP_IN_ORDER" => {
                let order = u32s(kv["order"]);
                let table = elist(kv["table"]);
                assert_eq!(es(&lkp_in_order(&table, &order)), kv["out"], "{}", line);
            }
            "LKP_BY_VARIABLE" => {
                let order = u32s(kv["order"]);
                let by_round = elist(kv["by_round"]);
                assert_eq!(
                    es(&lkp_by_variable(&by_round, &order)),
                    kv["out"],
                    "{}",
                    line
                );
            }
            "LKP_IN_ORDER_12" => {
                let order = u32s(kv["order"]);
                let table = mkvec(1 << 12, 120);
                assert_eq!(es(&lkp_in_order(&table, &order)), kv["out"], "{}", line);
            }
            "LKP_BY_VARIABLE_12" => {
                let order = u32s(kv["order"]);
                let by_round = mkvec(1 << 12, 130);
                assert_eq!(
                    es(&lkp_by_variable(&by_round, &order)),
                    kv["out"],
                    "{}",
                    line
                );
            }
            "LKP_SUMMAND" => match kv["kind"] {
                "product" => {
                    let s = lkp_summand_product();
                    summand_meta(&s, &kv, line);
                    let out = (s.at)(&[], &elist(kv["y"]));
                    assert_eq!(es(&out), kv["out"], "{}", line);
                }
                "tie_first" => {
                    let s = lkp_summand_tie(true, e(kv["a"]));
                    summand_meta(&s, &kv, line);
                    let out = (s.at)(&[], &elist(kv["y"]));
                    assert_eq!(es(&out), kv["out"], "{}", line);
                }
                "tie" => {
                    let s = lkp_summand_tie(false, e(kv["a"]));
                    summand_meta(&s, &kv, line);
                    let out = (s.at)(&[], &elist(kv["y"]));
                    assert_eq!(es(&out), kv["out"], "{}", line);
                }
                "bits" => {
                    let s = lkp_summand_bits();
                    summand_meta(&s, &kv, line);
                    let out = (s.at)(&[], &elist(kv["y"]));
                    assert_eq!(es(&out), kv["out"], "{}", line);
                }
                "leaves" => {
                    let S = &publics[kv["public"]];
                    let shape = lkp_shape(S, e(kv["theta"]));
                    let order = u32s(kv["order"]);
                    let by_round = elist(kv["by_round"]);
                    let s = lkp_summand_leaves(&shape, e(kv["alpha"]), &order);
                    summand_meta(&s, &kv, line);
                    let out = (s.at)(&by_round, &[]);
                    assert_eq!(es(&out), kv["out"], "{}", line);
                }
                other => panic!("unknown summand kind {}", other),
            },
            "LKP_COUNT" => {
                let S = &publics[kv["public"]];
                let keys = elist(kv["keys"]);
                let left: Vec<bool> = if kv["left"] == "-" {
                    Vec::new()
                } else {
                    let mut l = vec![false; keys.len()];
                    for i in u32s(kv["left"]) {
                        l[i as usize] = true;
                    }
                    l
                };
                let mut bits = Vec::new();
                let ok = lkp_count(S, &keys, &mut bits, &left);
                assert_eq!((ok as u8).to_string(), kv["ok"], "{}", line);
                assert_eq!(es(&bits), kv["bits"], "{}", line);
            }
            "LKP_LIVE_BLOCKS" => {
                let blocks = lkp_live_blocks(kv["live"].parse().unwrap());
                let s = if blocks.is_empty() {
                    "-".to_string()
                } else {
                    blocks
                        .iter()
                        .map(|(first, bits)| format!("{}:{}", first, bits))
                        .collect::<Vec<_>>()
                        .join(";")
                };
                assert_eq!(s, kv["blocks"], "{}", line);
            }
            "LKP_ON_BLOCK" => {
                let p: Vec<&str> = kv["block"].split(':').collect();
                let block = (p[0].parse().unwrap(), p[1].parse().unwrap());
                let mut v = Tensor::default();
                v.scalar = e(kv["scalar"]);
                for t in 0..5u64 {
                    v.push(mk(10 + t), mk(20 + t));
                }
                let part = lkp_on_block(&v, 3, block);
                assert_eq!(part.vars().to_string(), kv["vars"], "{}", line);
                assert_eq!(e_str(part.scalar), kv["part_scalar"], "{}", line);
                let at: Vec<E> = (0..32).map(|j| part.at(j)).collect();
                assert_eq!(es(&at), kv["at"], "{}", line);
            }
            other => panic!("unknown vector tag {}: {}", other, line),
        }
        seen += 1;
    }
    assert!(seen > 0);
    assert!(publics.len() >= 12);
    assert!(publics.contains_key("range"));
}
